-- 시연용 예시 글(자동 생성: tools/make-seed.mjs). 고정 id + INSERT OR IGNORE라 여러 번 실행해도 중복되지 않음
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9001, 'qna', 'wage', '편의점초보', '알바', '수습이라고 시급 9,800원 준다는데 괜찮은 건가요?', '이번 달부터 편의점에서 주 3일 일하기 시작했어요. 사장님이 처음 3개월은 수습이라서 시급 9,800원이고 그다음부터 올려 준다고 하네요. 계약 기간은 일단 6개월로 하자고 했어요. 수습이면 원래 이렇게 덜 받는 건가요?', NULL, '-', 'sample', 1794704400000, 5, 2, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90010, 9001, '알바3년차', '수습이라고 최저임금보다 덜 줄 수 있는 건 계약 기간이 1년 이상일 때만이라고 알고 있어요. 6개월 계약이면 해당 안 될 것 같아요. 법 안내에 수습 카드 한번 보세요.', '-', 'sample', 1794708000000, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90011, 9001, '편의점초보', '헉 감사합니다. 수습 카드 읽어 보고 사장님께 다시 여쭤볼게요.', '-', 'sample', 1794711600000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9002, 'qna', 'allowance', '카페알바생', '알바', '주 15시간 일하는데 주휴수당 받을 수 있나요?', '평일 3일, 하루 5시간씩 일해요. 계약서에는 주휴수당 얘기가 없어요. 15시간 딱 맞으면 받을 수 있는 건지 궁금합니다.', NULL, '-', 'sample', 1794805200000, 4, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90020, 9002, '지나가던직장인', '1주에 정해진 근로시간이 15시간 이상이고 그 주에 빠지지 않고 나가면 유급 주휴일이 생긴다고 해요. 정확한 건 1350에 물어보시는 게 제일 확실해요.', '-', 'sample', 1794808800000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9003, 'qna', 'hours', '주말근무중', '알바', '6시간 근무인데 쉬는 시간이 아예 없어요', '주말에 식당에서 오전 11시부터 오후 5시까지 일하는데, 바빠서 쉬는 시간이 따로 없고 서서 밥을 먹어요. 원래 이런가요?', NULL, '-', 'sample', 1794913200000, 2, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90030, 9003, '알바3년차', '4시간 일하면 30분 이상 쉬는 시간을 근무 중간에 줘야 한다고 법 안내 휴게시간 카드에 나와 있어요.', '-', 'sample', 1794916800000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9004, 'qna', 'insurance', '방학알바', '알바', '두 달짜리 단기 알바도 4대보험 가입하나요?', '방학 동안 두 달만 물류센터에서 일하는데, 4대보험 얘기를 들었어요. 짧게 일해도 가입하는 건가요?', NULL, '-', 'sample', 1794960000000, 1, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90040, 9004, '인사팀신입', '보험마다 기준이 달라서 근무 시간이랑 기간에 따라 달라요. 법 안내의 사회보험 카드에 기준이 정리돼 있어요.', '-', 'sample', 1794963600000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9005, 'story', 'dismissal', '그만둔사람', '알바', '카톡으로 "내일부터 나오지 마" 받았던 경험', '4개월 정도 일한 가게에서 갑자기 카톡으로 내일부터 나오지 말라는 연락을 받았어요. 너무 당황해서 1350에 전화했더니, 3개월 넘게 일했으면 해고를 30일 전에 알려야 하고 그러지 않았으면 30일분 임금을 받을 수 있다는 설명을 들었어요. 비슷한 일 겪는 분들은 카톡 내용부터 꼭 저장해 두세요.', NULL, '-', 'sample', 1794661200000, 6, 2, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90050, 9005, '카페알바생', '저장해 두라는 팁 감사해요. 저도 대화는 다 캡처해 두는 중이에요.', '-', 'sample', 1794697200000, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90051, 9005, '지나가던직장인', '해고 예고는 일한 기간이 3개월 미만이면 예외라고 하니 기간도 같이 확인해 보세요.', '-', 'sample', 1794700800000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9006, 'story', 'contract', '첫계약', '인턴', '계약서 없이 일하다가 요청해서 받았어요', '인턴 첫 주에 계약서를 안 써서 조심스럽게 요청드렸더니 다음 날 바로 써 주셨어요. 임금이랑 근무시간, 휴일이 적혀 있는지 확인하고 사본도 받았습니다. 말하기 어려웠는데 막상 하니까 별일 아니었어요.', NULL, '-', 'sample', 1794823200000, 3, 0, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9007, 'share', 'wage', '점검해봄', '알바', '계약서 점검해 봤더니 위험 1건 나왔어요', '샘플 말고 제 계약서로 점검해 봤는데 최저임금 쪽이 걸렸어요. 사장님께 어떻게 말씀드려야 할지 고민이에요.', '[{"level":"위험","title":"2026년 최저임금(시급 10,320원)보다 낮을 수 있어요"},{"level":"주의","title":"주휴일이 적혀 있지 않아요"},{"level":"참고","title":"계약서 작성일이 비어 있어요"}]', '-', 'sample', 1794992400000, 2, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90070, 9007, '알바3년차', '결과 화면 상세 보기에 근거 조문이 나오니까 그 부분을 보여 드리면서 얘기해 보세요.', '-', 'sample', 1794996000000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9008, 'share', 'hours', '야간근무자', '계약직', '근로시간 주의 1건 나왔네요', '하루 9시간으로 적혀 있어서 주의가 떴어요. 연장근로 수당이 따로 있는지 확인해 보려고요.', '[{"level":"주의","title":"기본 근로시간(하루 8시간·주 40시간)을 넘어요"}]', '-', 'sample', 1795046400000, 0, 0, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9009, 'tip', 'wage', '꼼꼼이', '수습', '급여 문제 생기기 전에 남겨 두면 좋은 기록', '1) 계약서 사진(서명 전·후 둘 다) 2) 매달 급여명세서나 통장 입금 내역 캡처 3) 실제 출퇴근 시간 메모(날짜별) 4) 업무 지시 메시지. 나중에 상담받을 때 이 기록이 있으면 설명이 훨씬 쉬워요.', NULL, '-', 'sample', 1794571200000, 4, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90090, 9009, '그만둔사람', '이거 진짜 중요해요. 저도 기록 덕분에 상담이 쉬웠어요.', '-', 'sample', 1794614400000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9010, 'tip', 'etc', '상담후기', '기타', '1350 상담 전화 이용 팁', '고용노동부 고객상담센터는 국번 없이 1350, 평일 9시~18시예요(통화료 유료). 전화하기 전에 근무 기간, 시급, 근무 시간, 사업장 인원을 메모해 두면 상담이 빨라요.', NULL, '-', 'sample', 1794888000000, 2, 0, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9011, 'free', NULL, '새내기알바', '알바', '첫 알바 시작했어요!', '오늘 첫 출근했어요. 아직 모르는 게 많지만 계약서는 꼭 받아 두라고 해서 받았습니다.', NULL, '-', 'sample', 1795042800000, 1, 1, 1);
INSERT OR IGNORE INTO comments (id, post_id, nick, body, pw, ip, created, sample) VALUES (90110, 9011, '카페알바생', '축하해요! 화이팅입니다.', '-', 'sample', 1795044600000, 1);
INSERT OR IGNORE INTO posts (id, board, topic, nick, job, title, body, share, pw, ip, created, likes, comments, sample) VALUES (9012, 'free', NULL, '주말근무중', '알바', '다들 알바 몇 개째 하세요?', '저는 이번이 세 번째예요. 다들 어떤 알바가 제일 괜찮았나요?', NULL, '-', 'sample', 1795050000000, 0, 0, 1);
